import torch.nn as nn
import torch

class AutoEncoder(nn.Module):
    def __init__(self):
        super().__init__()
        self.enc = nn.Linear(64, 16)
        self.dec = nn.Linear(16, 64)
    def forward(self, x):
        return self.dec(self.enc(x))

model = AutoEncoder()
x = torch.rand((1, 64))
out = model(x)
